# The old brand context (AgentBrandContext) becomes context entries
# (design/p2_contract.md 11d). Historical models only; the apex helper is
# a copy, because a migration must not import app code that can change.
_TWO_LABEL_TLDS = {
    "co.uk", "co.jp", "co.kr", "co.nz", "co.in", "co.za", "co.il",
    "com.au", "com.br", "com.cn", "com.mx", "com.tr", "com.sg", "com.hk",
    "com.tw", "com.ar", "com.pl",
    "ac.uk", "gov.uk", "org.uk",
    "edu.au", "gov.au",
    "ne.jp", "or.jp", "go.jp",
}
_TITLE_MAX = 120
_BODY_MAX = 4000


def _apex(url):
    try:
        host = (urlsplit(url if "://" in url else f"https://{url}").hostname or "").strip(".")
    except ValueError:
        return ""
    parts = host.lower().split(".")
    last_two = ".".join(parts[-2:])
    return ".".join(parts[-3:]) if last_two in _TWO_LABEL_TLDS and len(parts) > 2 else last_two


def _clip_at_word(text, limit):
    if len(text) <= limit:
        return text
    cut = text[:limit]
    return (cut.rsplit(" ", 1)[0] if " " in cut else cut).rstrip()


