    for row in BrandContext.objects.select_related("website").iterator():
        website = row.website
        if Entry.objects.filter(website_id=website.pk).exists():
            continue
        user_id = row.updated_by_id
        positions = {}

        def add(section, title, body):
            position = positions.get(section, 0)
            positions[section] = position + 1
            return Entry.objects.create(
                website_id=website.pk, section=section, title=title[:_TITLE_MAX],
                body=body[:_BODY_MAX], status="active", origin="migrated", position=position,
                revision=1, created_by_id=user_id, updated_by_id=user_id,
            )

        if (row.audience or "").strip():
            add("audience", "Audience", row.audience.strip())
        if (row.voice or "").strip():
            add("execution", "Voice", row.voice.strip())
        for rule in row.rules or []:
            rule = str(rule or "").strip()
            if rule:
                title = _clip_at_word(rule, _TITLE_MAX)
                add("execution", title, rule if title != rule else "")
        site_apex = _apex(website.url or "")
        for offering in row.offerings or []:
            if not isinstance(offering, dict):
                continue
            name = str(offering.get("name") or "").strip()
            description = str(offering.get("description") or "").strip()
            url = str(offering.get("url") or "").strip()
            on_site = bool(url) and bool(site_apex) and _apex(url) == site_apex
            if url and not on_site:
                description = f"{description}\nLink: {url}" if description else f"Link: {url}"
            if not name and not description:
                continue
            entry = add("offerings", name, description)
            if on_site:
                Reference.objects.create(
                    entry=entry, website_id=website.pk, kind="page", url=url[:2000],
                    state="unchecked",
                )


